package edu.eci.cvds.ECIReserves.service;import edu.eci.cvds.ECIReserves.model.Laboratory;import edu.eci.cvds.ECIReserves.model.Reservation;import edu.eci.cvds.ECIReserves.repository.LaboratoryRepository;import edu.eci.cvds.ECIReserves.repository.ReservationRepository;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.time.ZoneId;import java.util.*;import java.util.function.Consumer;import java.util.function.Predicate;import java.util.stream.Collectors;@Servicepublic class LaboratoryService {    private final LaboratoryRepository laboratoryRepository;    private final ReservationRepository reservationRepository;    @Autowired    public LaboratoryService(LaboratoryRepository laboratoryRepository, ReservationRepository reservationRepository) {        this.laboratoryRepository = laboratoryRepository;        this.reservationRepository = reservationRepository;    }    public Laboratory addLab(Laboratory lab) {        if (!isOkLab(lab)) {            throw new IllegalArgumentException("Datos del laboratorio inválidos");        }        return laboratoryRepository.save(lab);    }    @Transactional    public Laboratory updateLab(String id, Laboratory updatedLab) {        Optional<Laboratory> optionalLab = laboratoryRepository.findById(id);        if (optionalLab.isEmpty()) {            System.out.println("⚠️ Laboratorio con ID " + id + " no encontrado en la base de datos");            throw new NoSuchElementException("Laboratorio no encontrado");        }        Laboratory existingLab = optionalLab.get();        System.out.println("✅ Laboratorio encontrado: " + existingLab.getName());        updateFieldIfValid(updatedLab.getName(), existingLab::setName);        updateFieldIfValid(updatedLab.getComputers(), existingLab::setComputers, val -> val > 0);        updateFieldIfValid(updatedLab.getCapacity(), existingLab::setCapacity, val -> val > 0);        updateFieldIfValid(updatedLab.getOpeningTime(), existingLab::setOpeningTime);        updateFieldIfValid(updatedLab.getClosingTime(), existingLab::setClosingTime);        return laboratoryRepository.save(existingLab);    }    @Transactional    public void deleteLab(String id){        laboratoryRepository.deleteById(id);    }    public List<Laboratory> findAvailableLabsBetween(Date start, Date end) {        List<Laboratory> allLabs = laboratoryRepository.findByTimeBetween(start, end);        return allLabs.stream()                .filter(lab -> isLabAvailable(lab.getId(), start, end))                .collect(Collectors.toList());    }    public boolean isLabAvailable(String labId, Date start, Date end) {        List<Reservation> reservations = reservationRepository.findByLaboratoryIdAndDateTimeBetween(labId, start, end);        return reservations.isEmpty();    }    public List<Laboratory> searchLabs(String name, Integer minCapacity, Integer minComputers){        return laboratoryRepository.findByNameCapacityAndComputers(name, minCapacity, minComputers);    }    public List<Laboratory> getLabsByName(String name) {        return laboratoryRepository.findByName(name);    }    public List<Laboratory> getLabsByCapacity(int minCapacity) {        return laboratoryRepository.findByCapacityGreaterThanEqual(minCapacity);    }    public List<Laboratory> getLabsByComputers(int minComputers) {        return laboratoryRepository.findByComputersGreaterThanEqual(minComputers);    }    public List<Laboratory> getLabsByOpeningTime(LocalDateTime openingTime) {        return laboratoryRepository.findByOpeningTime(openingTime);    }    public List<Laboratory> getLabsByClosingTime(LocalDateTime closingTime) {        return laboratoryRepository.findByClosingTime(closingTime);    }    public LaboratoryRepository getRepository() {        return laboratoryRepository;    }    private boolean isOkLab(Laboratory lab){        if(lab.getCapacity() <= 0){return false;}        if(lab.getId() == null){return false;}        if(lab.getName() == null){return false;}        if(lab.getDescription() == null){return false;}        if (lab.getComputers() == null || lab.getComputers() < 0) { return false; }        if(lab.getOpeningTime() == null){return false;}        if(lab.getClosingTime() == null){return false;}        return true;    }    private <T> void updateFieldIfValid(T newValue, Consumer<T> setter, Predicate<T> condition) {        if (newValue != null && condition.test(newValue)) {            setter.accept(newValue);        }    }    private <T> void updateFieldIfValid(T newValue, Consumer<T> setter) {        if (newValue != null) {            setter.accept(newValue);        }    }    private Date convertToDate(LocalDateTime dateToConvert) {        return Date.from(dateToConvert.atZone(ZoneId.systemDefault()).toInstant());    }}